import { onceForKey } from "@/lib/api-idempotency";
import { MAX_IDEMPOTENCY_RECORD_BYTES } from "@/lib/api-idempotency-rules";
import { store as redis } from "../../../tests/redis-stub";
import { done, is, part } from "../../../tests/check";

const original = redis.pipeline.bind(redis);
const request = () => new Request("https://example.test/api/v1/leads", { method: "POST", headers: { "Idempotency-Key": "review-receipt" } });
let runs = 0;
const call = (run = async () => { runs++; return { response: Response.json({ ok: true }), effect: "done" as const }; }) =>
  onceForKey(request(), "synthetic-store", "/api/v1/leads", { email: "synthetic@example.test" }, 8192, run);
function fresh() { redis.pipeline = original; redis.clear(); runs = 0; }
function fault(command: string, mode: "bad" | "lost-after") {
  let fired = false;
  redis.pipeline = async (commands) => {
    const target = commands.some(c => c[0] === command && (command !== "SET" || c.includes("NX")));
    if (target && !fired) {
      fired = true;
      if (mode === "lost-after") { await original(commands); throw new Error("synthetic receipt lost after apply"); }
      return [];
    }
    return original(commands);
  };
}

async function main() {
  part("Unknown GET and claim receipts never dispatch the write");
  fresh(); fault("GET", "bad");
  is("unknown read returns 503", (await call()).status, 503);
  is("unknown read dispatched nothing", runs, 0);
  fresh(); fault("SET", "bad");
  is("unknown claim returns 503", (await call()).status, 503);
  is("unknown claim dispatched nothing", runs, 0);
  fresh(); fault("SET", "lost-after");
  is("lost applied claim returns 503", (await call()).status, 503);
  redis.pipeline = original;
  is("repeat sees pending claim", (await call()).status, 409);
  is("neither request dispatched", runs, 0);

  part("Lost final receipt and an uncertain write never dispatch twice");
  fresh();
  let lost = false;
  redis.pipeline = async commands => {
    const result = await original(commands);
    if (!lost && commands.some(c => c[0] === "SET" && c.includes("XX"))) { lost = true; throw new Error("synthetic final receipt lost"); }
    return result;
  };
  is("first completed answer still returns", (await call()).status, 200);
  is("repeat replays applied record", (await call()).headers.get("Idempotent-Replayed"), "true");
  is("write ran once", runs, 1);
  fresh();
  let thrown = false;
  try { await call(async () => { runs++; throw new Error("synthetic write may have acted"); }); } catch { thrown = true; }
  is("thrown write remains an error", thrown, true);
  is("repeat after throw held", (await call()).status, 409);
  is("thrown write not run again", runs, 1);
  fresh();
  is("uncertain 502 first returned", (await call(async () => { runs++; return { response: Response.json({ error: "unknown" }, { status: 502 }), effect: "maybe" }; })).status, 502);
  is("uncertain 502 repeat held", (await call()).status, 409);
  is("uncertain write ran once", runs, 1);

  part("Inherited record-size blocker through the new wrapper, not a new finding");
  fresh();
  const body = JSON.stringify({ value: "\"".repeat(3998) });
  const first = await call(async () => { runs++; return { response: new Response(body, { headers: { "Content-Type": "application/json" } }), effect: "done" }; });
  const key = [...redis.keys()].find(k => k.startsWith("nl:api:idem:"))!;
  const [raw] = await original([["GET", key]]);
  const measured = { responseBytes: Buffer.byteLength(body), recordBytes: Buffer.byteLength(String(raw)), declaredRecordBytes: MAX_IDEMPOTENCY_RECORD_BYTES };
  console.log("KNOWN_PARENT_RECORD_SIZE", JSON.stringify(measured));
  is("synthetic body fits advertised answer bound", measured.responseBytes <= 8192, true);
  is("wrapper stores over declared record bound (known parent MED)", measured.recordBytes > measured.declaredRecordBytes, true);
  is("first response delivered", first.status, 200);
  redis.pipeline = original;
  done();
}
void main();

